	qaTombDirNew = "Anchor Point S01 (2024)"

	qaTombEp1Old = qaTombDirOld + "/Anchor Point S01E01.mkv"
	qaTombEp2Old = qaTombDirOld + "/Anchor Point S01E02.mkv"
