	// The staged positions (the slot discriminators; every value sits below
	// the 108 s completion floor so the watch detector never fires): the
	// stranded seeds, the conflict viewer's live overwrite, and the carry
	// leg's reseed.
	qaTombPosACarry    = int64(7)  // viewer A stranded on E01-old -> carries to E01-new
	qaTombPosBStranded = int64(11) // viewer B stranded on E02-old -> carries to E02-new
	qaTombPosBLive     = int64(45) // viewer B's live row on E02-new (wins its slot)
	qaTombPosBReseed   = int64(22) // viewer B's wave-2 stranded reseed on E02-old
	qaTombPosACarry3   = int64(8)  // viewer A stranded on E03-old -> carries to E03-new

	// qaTombPosEchoUnknown tells qaTombPutWatched the id is tombstoned: the
	// state echo's position rides the JOINED progress read, which hides
	// deleted-item rows, so a dead id echoes 0 — the position assert is
	// skipped and the raw ledger reads own the stock truth.
	qaTombPosEchoUnknown = int64(-1)

	qaTombUsername  = "qa-tomb-user"
	qaTombPassword  = "qa-tomb-passphrase-1"
	qaTombGroupName = "QA Tomb Grants"
	qaTombAdmin     = "qa-tomb-admin-token"

	// The stub upstream's derived identity (the parser strips the year tag,
