	qaTombBEp1Old = qaTombDirBOld + "/Beacon Line S01E01.mkv"
	qaTombBEp2Old = qaTombDirBOld + "/Beacon Line S01E02.mkv"
	qaTombBEp3Old = qaTombDirBOld + "/Beacon Line S01E03.mkv"
	qaTombBEp4Old = qaTombDirBOld + "/Beacon Line S01E04.mkv"
	qaTombBEp1New = qaTombDirBNew + "/Beacon Line S01E01.mkv"
	qaTombBEp2New = qaTombDirBNew + "/Beacon Line S01E02.mkv"
	qaTombBEp3New = qaTombDirBNew + "/Beacon Line S01E03.mkv"

	// B's staged positions (every value distinct from Series A's — a
