	// below the 108 s completion floor.
	qaTombPosBEp1    = int64(33) // admin stranded on B-E01-old -> carries to B-E01-new
	qaTombPosBEp2    = int64(34) // viewer B stranded on B-E02-old -> carries to B-E02-new
	qaTombPosBEp3    = int64(35) // viewer B stranded on B-E03-old -> carries to B-E03-new
	qaTombPosBEp4    = int64(36) // admin stranded on B-E04-old -> RETAINED (no successor)
	qaTombPosAXProbe = int64(41) // user re-armed stock on dead A-E01-old -> carries WITHIN A (ep1-new user slot), refused by B

	// B's stub identity (the search routes by the parsed title, so B's scan
