// qaTombStartUpstream starts the stub; its URL feeds the server env's
// MELLIFERA_SHIKIMORI_UPSTREAM (the plugin child bakes it into every fetch
// template — the hermetic seam). The search endpoint answers the single
// candidate immediately; every non-anime path 404s (the art fetcher's poster
// probes — tolerated background WARNs).
func qaTombStartUpstream(t *testing.T) *qaTombUpstream {
	t.Helper()
	up := &qaTombUpstream{}
	writeJSON := func(w http.ResponseWriter, v any) {
		w.Header().Set("Content-Type", "application/json")
		if err := json.NewEncoder(w).Encode(v); err != nil {
			t.Errorf("stub write: %v", err)
		}
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/api/animes", func(w http.ResponseWriter, r *http.Request) {
		var cand map[string]any
		switch r.URL.Query().Get("search") {
		case qaTombSearchTitle:
			cand = qaTombAnime()
		case qaTombSearchTitleB:
			cand = qaTombAnimeB()
		default:
			http.NotFound(w, r)
			return
		}
		writeJSON(w, []map[string]any{cand})
	})
	mux.HandleFunc("/api/animes/", func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/api/animes/" + strconv.Itoa(qaTombShikiID):
			writeJSON(w, qaTombAnime())
		case "/api/animes/" + strconv.Itoa(qaTombShikiID) + "/episodes":
			writeJSON(w, qaTombEpisodeEntries())
		case "/api/animes/" + strconv.Itoa(qaTombShikiIDB):
			writeJSON(w, qaTombAnimeB())
		case "/api/animes/" + strconv.Itoa(qaTombShikiIDB) + "/episodes":
			writeJSON(w, qaTombEpisodeEntriesB())
		default:
			http.NotFound(w, r) // roles + graphql poster + art probes: soft legs
		}
	})
	up.srv = httptest.NewServer(mux)
	up.baseURL = up.srv.URL
	t.Cleanup(up.srv.Close)
	return up
}

// qaTombUpstream is the fake shikimori origin (the qaRescan stub idiom, own
// payload maps).
type qaTombUpstream struct {
	baseURL string
	srv     *httptest.Server
}

// qaTombWriteFixtures builds the fixture library: one serial directory, three
// probeable 120 s episodes (the completion floor 108 sits above every staged
// position), no sidecars — the scans must be warning-free and the counts
// exact (1 serial record + 3 episodes).
func qaTombWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	dir := filepath.Join(root, qaTombDirOld)
	qaAcctMedia(t, filepath.Join(dir, "Anchor Point S01E01.mkv"))
	qaAcctMedia(t, filepath.Join(dir, "Anchor Point S01E02.mkv"))
	qaAcctMedia(t, filepath.Join(dir, "Anchor Point S01E03.mkv"))
	return root
}

// qaTombWriteSeriesB builds Series B's fixture directory: four probeable
// 120 s episodes. B joins the library AFTER 2.4's waves (its own intro scan),
// so every byte-frozen 2.4 assert keeps its authored truth — wave 0 and the
// rename rescan counted Series A alone. E04 exists only pre-rename: the
// rename REMOVES it, giving B one dead row with no successor (the
// retained-stock probe).
func qaTombWriteSeriesB(t *testing.T, root string) {
	t.Helper()
	dir := filepath.Join(root, qaTombDirBOld)
	for _, name := range []string{
		"Beacon Line S01E01.mkv", "Beacon Line S01E02.mkv",
		"Beacon Line S01E03.mkv", "Beacon Line S01E04.mkv",
	} {
		qaAcctMedia(t, filepath.Join(dir, name))
	}
}

// qaTombStartJoint boots the joint: the seven server-side binaries + the
// shikimori plugin (upstream pinned to the stub), the REAL cmd/mellifera
// subprocess, and the serial library. The scan stays with the caller.
func qaTombStartJoint(t *testing.T) *qaTombJoint {
	t.Helper()
	up := qaTombStartUpstream(t)
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-tomb-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-tomb-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-tomb-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-tomb-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-tomb-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-tomb-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-tomb-grabber", "./plugins/frame-grabber"),
	}, up.baseURL, tmp, qaTombAdmin)
	return &qaTombJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		admin:  qaTombAdmin,
	}
}

// ---- staging through the REAL admin surface -----------------------------------

// qaTombCreateUser POSTs /admin/users and returns the created id.
func qaTombCreateUser(t *testing.T, j *qaTombJoint) int64 {
	t.Helper()
	var resp struct {
		ID int64 `json:"id"`
	}
	status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/admin/users", j.admin,
		map[string]string{"username": qaTombUsername, "password": qaTombPassword}, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create user %s: HTTP %d, want 201", qaTombUsername, status)
	}
	if resp.ID == 0 {
		t.Fatalf("create user %s: zero id served", qaTombUsername)
	}
	return resp.ID
}

// qaTombGrantUser grants viewer B the library through the real accounts
// surface (group + membership + collection grant — grant-based default
// visibility), so B's progress/state writes and reads resolve the item.
func qaTombGrantUser(t *testing.T, j *qaTombJoint) {
	t.Helper()
	var group struct {
		ID int64 `json:"id"`
	}
	status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/admin/groups", j.admin,
		map[string]string{"name": qaTombGroupName}, &group)
	if status != http.StatusCreated {
		t.Fatalf("create group: HTTP %d, want 201", status)
	}
	url := j.srv.baseURL + "/api/v1/admin/groups/" + strconv.FormatInt(group.ID, 10) + "/users"
	if status := doRequest(t, j.client, http.MethodPost, url, j.admin,
		map[string]string{"username": qaTombUsername}, nil); status != http.StatusNoContent {
		t.Fatalf("add member: HTTP %d, want 204", status)
	}
	url = j.srv.baseURL + "/api/v1/admin/groups/" + strconv.FormatInt(group.ID, 10) + "/collections"
	if status := doRequest(t, j.client, http.MethodPost, url, j.admin,
		map[string]int64{"library_id": j.lib}, nil); status != http.StatusNoContent {
		t.Fatalf("grant library: HTTP %d, want 204", status)
	}
}

// qaTombLogin mints viewer B's session token through the REAL login endpoint.
func qaTombLogin(t *testing.T, j *qaTombJoint) string {
	t.Helper()
	var resp struct {
		Token string `json:"token"`
	}
	status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/auth/login", "",
		map[string]string{"username": qaTombUsername, "password": qaTombPassword}, &resp)
	if status != http.StatusOK {
		t.Fatalf("login %s: HTTP %d, want 200", qaTombUsername, status)
	}
	if resp.Token == "" {
		t.Fatalf("login %s: empty token served", qaTombUsername)
	}
	return resp.Token
}

// ---- the real write paths ------------------------------------------------------

// qaTombPutProgress PUTs one progress position as token (the caller's ledger
// slot), asserting the 200 echo's position. Legal on a tombstoned id too: the
// handler's store reads are status-unfiltered (PutProgress resolves the item
// by id, never by status) — the write path this feature's carry depends on.
func qaTombPutProgress(t *testing.T, j *qaTombJoint, token, itemID string, pos int64) {
	t.Helper()
	var echo struct {
		ItemID          string `json:"item_id"`
		PositionSeconds int64  `json:"position_seconds"`
	}
	status := doRequest(t, j.client, http.MethodPut, j.srv.baseURL+"/api/v1/progress/"+itemID, token,
		map[string]int64{"position_seconds": pos}, &echo)
	if status != http.StatusOK {
		t.Fatalf("PUT progress %s as %q: HTTP %d, want 200", itemID, token, status)
	}
	if echo.ItemID != itemID || echo.PositionSeconds != pos {
		t.Fatalf("PUT progress %s echo = %+v, want item %s position %d", itemID, echo, itemID, pos)
	}
}

// qaTombPutWatched PUTs the watched state as token, asserting the 200 echo and
// returning its completed_at stamp (RFC3339Nano — the store persists ledger
// stamps in the same format, so the moved row's raw stamp must equal it).
// wantPos asserts the echo's position — pass qaTombPosEchoUnknown for a
// TOMBSTONED id: the echo's position comes from the JOINED progress read,
// which hides deleted-item rows, so a dead id echoes position 0 regardless of
// its real stored slot (the raw ledger asserts cover the actual stock).
func qaTombPutWatched(t *testing.T, j *qaTombJoint, token, itemID string, wantPos int64) string {
	t.Helper()
	var echo struct {
		ItemID          string `json:"item_id"`
		State           string `json:"state"`
		PositionSeconds int64  `json:"position_seconds"`
		CompletedAt     string `json:"completed_at"`
	}
	status := doRequest(t, j.client, http.MethodPut, j.srv.baseURL+"/api/v1/items/"+itemID+"/state", token,
		map[string]string{"state": "watched"}, &echo)
	if status != http.StatusOK {
		t.Fatalf("PUT state watched %s: HTTP %d, want 200", itemID, status)
	}
	if echo.ItemID != itemID || echo.State != "watched" || echo.CompletedAt == "" {
		t.Fatalf("PUT state watched %s echo = %+v, want item %s watched with a stamp", itemID, echo, itemID)
	}
	if wantPos != qaTombPosEchoUnknown && echo.PositionSeconds != wantPos {
		t.Fatalf("PUT state watched %s echo position = %d, want %d", itemID, echo.PositionSeconds, wantPos)
	}
	return echo.CompletedAt
}

// qaTombGetProgressPos reads one item's position on the wire as token; ok=false
// on a 404 (the row absent from the caller's slot).
func qaTombGetProgressPos(t *testing.T, j *qaTombJoint, token, itemID string) (int64, bool) {
	t.Helper()
	var resp struct {
		ItemID          string `json:"item_id"`
		PositionSeconds int64  `json:"position_seconds"`
	}
	status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress/"+itemID, token, nil, &resp)
	if status == http.StatusNotFound {
		return 0, false
	}
	if status != http.StatusOK {
		t.Fatalf("GET progress %s: HTTP %d, want 200", itemID, status)
	}
	return resp.PositionSeconds, true
}

// qaTombRefresh kicks the operator re-enrichment for the given row ids through
// the real admin surface (POST /libraries/{id}/refresh, plugin serial-parser),
// asserting the 202 outcome: every named row stripped, none deferred.
func qaTombRefresh(t *testing.T, j *qaTombJoint, rowIDs ...string) {
	t.Helper()
	var resp struct {
		Queued   int `json:"queued"`
		Stripped int `json:"stripped"`
		Deferred int `json:"deferred"`
	}
	body := map[string]any{"plugin_id": "serial-parser", "row_ids": rowIDs}
	status := doRequest(t, j.client, http.MethodPost,
		j.srv.baseURL+"/api/v1/libraries/"+strconv.FormatInt(j.lib, 10)+"/refresh", j.admin, body, &resp)
	if status != http.StatusAccepted {
		t.Fatalf("refresh rows %v: HTTP %d, want 202", rowIDs, status)
	}
	if resp.Stripped != len(rowIDs) || resp.Deferred != 0 || resp.Queued != len(rowIDs) {
		t.Fatalf("refresh rows %v outcome = %+v, want stripped=%d deferred=0 queued=%d",
			rowIDs, resp, len(rowIDs), len(rowIDs))
	}
}

// ---- settle (active rows ready + queue idle) ----------------------------------

// qaTombWaitSettled waits for the joint's settle law: every series and item
// row of the library reads ready OR deleted (the tombstoned rows never return
// to ready — the settle law this feature owns: settle() early-returns unless
// the status is enriched), and the enrich queue's liveness counters report
// nothing pending and nothing in flight. The idle gate is the
// adoption-completion gate: statInFlight is released only after the row's
// persistRow AND its adoption fire (workItem's tail), so idle counters imply
// every enqueued pass's document writes AND adoption moves are durable.
// Deleted rows appear on the wire until the serve-side default exclusion lands
// (task 3.2) and vanish after — the helper reads only statuses, so it holds
// either way. Bounded by qaSerialDrainTimeout.
func qaTombWaitSettled(t *testing.T, j *qaTombJoint) {
	t.Helper()
	type enrichStats struct {
		Pending  int `json:"pending"`
		InFlight int `json:"in_flight"`
	}
	deadline := time.Now().Add(qaSerialDrainTimeout)
	var lastRows string
	var lastQueue, lastStatus int
	for {
		rowsReady := true
		lastRows = ""
		for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.lib) {
			if sr.Status != "ready" && sr.Status != "deleted" {
				rowsReady = false
				lastRows += "series " + sr.RelativePath + "=" + sr.Status + " "
			}
		}
		for _, it := range listItems(t, j.client, j.srv.baseURL, j.admin, j.lib) {
			if it.Status != "ready" && it.Status != "deleted" {
				rowsReady = false
				lastRows += "item " + it.RelativePath + "=" + it.Status + " "
			}
		}
		var resp struct {
			Enrich enrichStats `json:"enrich"`
		}
		status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/admin/status", j.admin, nil, &resp)
		idle := status == http.StatusOK && resp.Enrich.Pending == 0 && resp.Enrich.InFlight == 0
		lastQueue, lastStatus = resp.Enrich.Pending, status
		if rowsReady && idle {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("joint not settled within %s: non-settled rows [%s] enrich pending=%d (status %d)",
				qaSerialDrainTimeout, lastRows, lastQueue, lastStatus)
		}
		time.Sleep(probeInterval)
	}
}

// ---- the DIRECT ledger read (the provenance oracle — never the wire) -----------
//
// GetProgress/ListProgress hide rows whose item is deleted, and the watched
// wire surfaces are slot-scoped — the dead-slot emptiness law ("the dead rows
// hold nothing") is provable ONLY against the tables. The server's SQLite is
// opened read-only from the test process (WAL allows the concurrent reader;
// busy_timeout absorbs the writer's locks) — the qaAcctOpenLedger idiom.

// qaTombOpenLedger opens the server's SQLite file read-only.
func qaTombOpenLedger(t *testing.T, j *qaTombJoint) *sql.DB {
	t.Helper()
	dsn := "file:" + filepath.Join(j.srv.dataDir, "mellifera.db") + "?mode=ro&_pragma=busy_timeout(5000)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		t.Fatalf("open ledger read-only: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	return db
}

// qaTombWatchedRec is one watched_items ledger row's carried facts.
type qaTombWatchedRec struct {
	SeriesPath  string // series_relative_path (the move re-points it)
	CompletedAt string // verbatim across a move
}

// qaTombProgressSlots returns the (user_id -> position) map of EVERY
// playback_progress row for itemID, across all slots.
func qaTombProgressSlots(t *testing.T, db *sql.DB, itemID string) map[int64]int64 {
	t.Helper()
	rows, err := db.Query("SELECT user_id, position_seconds FROM playback_progress WHERE item_id = ?", itemID)
	if err != nil {
		t.Fatalf("read progress slots for %s: %v", itemID, err)
	}
	defer rows.Close()
	out := map[int64]int64{}
	for rows.Next() {
		var uid, pos int64
		if err := rows.Scan(&uid, &pos); err != nil {
			t.Fatalf("scan progress slot for %s: %v", itemID, err)
		}
		out[uid] = pos
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("read progress slots for %s: %v", itemID, err)
	}
	return out
}

// qaTombWatchedRows returns the (user_id -> rec) map of EVERY watched_items
// row for itemID, across all slots.
func qaTombWatchedRows(t *testing.T, db *sql.DB, itemID string) map[int64]qaTombWatchedRec {
	t.Helper()
	rows, err := db.Query(
		"SELECT user_id, series_relative_path, completed_at FROM watched_items WHERE item_id = ?", itemID)
	if err != nil {
		t.Fatalf("read watched rows for %s: %v", itemID, err)
	}
	defer rows.Close()
	out := map[int64]qaTombWatchedRec{}
	for rows.Next() {
		var uid int64
		var rec qaTombWatchedRec
		if err := rows.Scan(&uid, &rec.SeriesPath, &rec.CompletedAt); err != nil {
			t.Fatalf("scan watched row for %s: %v", itemID, err)
		}
		out[uid] = rec
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("read watched rows for %s: %v", itemID, err)
	}
	return out
}

// qaTombRowCount counts one table's rows for itemID — the dead-slot emptiness
// oracle.
func qaTombRowCount(t *testing.T, db *sql.DB, table, itemID string) int {
	t.Helper()
	var n int
	if err := db.QueryRow("SELECT COUNT(*) FROM "+table+" WHERE item_id = ?", itemID).Scan(&n); err != nil {
		t.Fatalf("count %s rows for %s: %v", table, itemID, err)
	}
	return n
}

// qaTombRowStatus reads one row's raw lifecycle status off the given table
// (items | series) — the store read no handler filters, stable across the
// task-3.2 serve-side default exclusion.
func qaTombRowStatus(t *testing.T, db *sql.DB, table, rowID string) string {
	t.Helper()
	var status string
	if err := db.QueryRow("SELECT status FROM "+table+" WHERE id = ?", rowID).Scan(&status); err != nil {
		t.Fatalf("read %s %s status: %v", table, rowID, err)
	}
	return status
}

// qaTombAssertRetainedStock pins one dead row's RETAINED stock byte-intact —
// 2.6's law through the real chain (the dead row is never dispatched, never
// fires the adoption hook, and is refused or legs-refused as a candidate, so
// its stock survives every queue pass): exactly one progress slot at wantPos
// for wantUser, exactly one watched row with the verbatim stamp and the NEVER
// re-pointed series path — the row never moved, so its stock never changed.
// Raw reads only: the joined wire reads hide deleted rows and could never
// prove retention.
func qaTombAssertRetainedStock(t *testing.T, phase, label string, db *sql.DB, itemID string, wantUser, wantPos int64, wantStamp, wantSeriesPath string) {
	t.Helper()
	if got := qaTombProgressSlots(t, db, itemID); len(got) != 1 || got[wantUser] != wantPos {
		t.Errorf("%s: %s progress slots = %v, want exactly slot %d at %d (the dead row's stock survives every queue pass — never moved, never destroyed)",
			phase, label, got, wantUser, wantPos)
	}
	recs := qaTombWatchedRows(t, db, itemID)
	if len(recs) != 1 {
		t.Errorf("%s: %s watched rows = %v, want exactly slot %d", phase, label, recs, wantUser)
	} else if rec := recs[wantUser]; rec.CompletedAt != wantStamp {
		t.Errorf("%s: %s watched completed_at = %q, want the seeded stamp %q verbatim", phase, label, rec.CompletedAt, wantStamp)
	} else if rec.SeriesPath != wantSeriesPath {
		t.Errorf("%s: %s watched series_relative_path = %q, want the never-moved source path %q", phase, label, rec.SeriesPath, wantSeriesPath)
	}
}

// ---- document reads -------------------------------------------------------------

// qaTombDoc decodes one raw document.
func qaTombDoc(t *testing.T, raw json.RawMessage) map[string]any {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode document: %v", err)
	}
	return doc
}

// qaTombViewTitle is the _view.title.value floor inline read (the adoption
// identity's title leg — adopt.go adoptTitleFloor's wire shape).
func qaTombViewTitle(doc map[string]any) string {
	view, _ := doc["_view"].(map[string]any)
	title, _ := view["title"].(map[string]any)
	s, _ := title["value"].(string)
	return s
}

// qaTombNamespace reads one plugin's sources namespace off a document.
func qaTombNamespace(t *testing.T, doc map[string]any, plugin string) map[string]any {
	t.Helper()
	sources, _ := doc["sources"].(map[string]any)
	ns, _ := sources[plugin].(map[string]any)
	if ns == nil {
		t.Fatalf("document carries no sources.%s namespace: %v", plugin, doc["sources"])
	}
	return ns
}

// qaTombSeriesParserTitle reads sources["serial-parser"].title off a series
// document — the bridge's floor leg (adopt.go adoptSeriesTitleFloor's read),
// composed by the REAL serial-parser Merge from dir_name_raw through the
// releasename grammar. This title's rename-stability (bracket tags and the
// season marker strip; the words stay) is the bridge precondition that makes
// a same-series carry land and a cross-series pair refuse.
func qaTombSeriesParserTitle(t *testing.T, raw json.RawMessage) string {
	t.Helper()
	doc := qaTombDoc(t, raw)
	sources, _ := doc["sources"].(map[string]any)
	ns, _ := sources["serial-parser"].(map[string]any)
	title, _ := ns["title"].(string)
	return title
}

// qaTombAssertEpisodeIdentity pins one episode document's ACTUAL post-scan
// identity state: the serial-parser namespace carries the (1, N) legs, and the
// title floor is EMPTY — a fresh scan's shikimori run is the single-fetch
// search shape (no extras, no episode titles, no route: source.go BuildRequest
// "A search stays single-fetch"; episode documents never match at Match), so
// no episode row ever carries sources.shikimori or a _view.title. This empty
// floor is the identity the adoption compares: "" == "" passes the title leg
// and the legs decide — the documented exact-equality identity, pinned here as
// the carry's precondition.
func qaTombAssertEpisodeIdentity(t *testing.T, phase, rel string, doc map[string]any, wantEpisode int64) {
	t.Helper()
	if got := qaTombViewTitle(doc); got != "" {
		t.Fatalf("%s: %q carries a title floor %q, want the empty post-scan floor (a fresh scan routes no episode titles)", phase, rel, got)
	}
	sources, _ := doc["sources"].(map[string]any)
	if _, has := sources["shikimori"]; has {
		t.Fatalf("%s: %q carries sources.shikimori %v, want none (episode documents never match at Match; the search shape fetches no extras)", phase, rel, sources["shikimori"])
	}
	ns := qaTombNamespace(t, doc, "serial-parser")
	season, _ := ns["season"].(float64)
	episode, _ := ns["episode"].(float64)
	if season != 1 || int64(episode) != wantEpisode {
		t.Fatalf("%s: %q parse facts = {season:%v episode:%v}, want {1 %d}", phase, rel, season, episode, wantEpisode)
	}
}

// TestQATombstoneAdoptionJoint is the Tier-1 joint contract of
// tombstone-lifecycle: the REAL scan→tombstone→queue→adopt chain re-keys a
// vanished serial's stranded watch state onto the identity-matched successor
// ids, empties the dead rows, and honors the conflicting live row.
func TestQATombstoneAdoptionJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tombstone adoption joint e2e: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — episodes cannot be probed; skipping (INV4: optional binary)")
	}

	j := qaTombStartJoint(t)
	root := qaTombWriteFixtures(t)
	j.lib = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.admin, root, "QA Tombstone Adoption")

	// ---- wave 0: the first scan settles the library --------------------------
	res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, j.lib)
	if res.Discovered != 4 || res.Persisted != 4 {
		t.Fatalf("first scan: discovered=%d persisted=%d, want 4/4 (1 serial record + 3 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Fatalf("first scan: warnings = %v, want none (clean fixture library)", res.Warnings)
	}
	qaTombWaitSettled(t, j)

	ep1Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp1Old)
	ep2Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp2Old)
	ep3Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp3Old)

	// The identity precondition, PINNED as actual behavior: every episode
	// document carries its (1, N) parse legs and an EMPTY title floor (the
	// search-only scan flow routes no episode titles — see
	// qaTombAssertEpisodeIdentity). The SERIES row's shikimori run landed its
	// namespace from the same single-candidate search — the only shikimori
	// write a fresh scan makes.
	for rel, dto := range map[string]itemDTO{
		qaTombEp1Old: ep1Old, qaTombEp2Old: ep2Old, qaTombEp3Old: ep3Old,
	} {
		qaTombAssertEpisodeIdentity(t, "wave 0", rel, qaTombDoc(t, dto.Document), int64(rel[len(rel)-len("E01.mkv")+2]-'0'))
	}
	var oldSeriesID string
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.lib) {
		if sr.RelativePath == qaTombDirOld {
			oldSeriesID = sr.ID
			seriesDoc := qaTombDoc(t, sr.Document)
			qaTombNamespace(t, seriesDoc, "shikimori") // the search run's namespace — landed
		}
	}
	if oldSeriesID == "" {
		t.Fatalf("first scan: no series row at %q", qaTombDirOld)
	}

	// Viewer B: a real user account granted the library (grant-based default
	// visibility), logged in through the real auth surface. Viewer A is the
	// env-admin token — the legacy slot-0 viewer (see the accounts joint).
	j.userID = qaTombCreateUser(t, j)
	qaTombGrantUser(t, j)
	j.user = qaTombLogin(t, j)

	// ---- wave 1 seeds: stranded state on the soon-to-die ids -----------------
	//
	// Both viewers write through the REAL surfaces: PUT /progress/{id} (the
	// playback position, sub-threshold so the completion detector never
	// fires) and PUT /items/{id}/state watched (the completion ledger).
	// E03-old stays UNSEEDED: its successor must carry nothing in wave 1 (the
	// negative identity case), then carry A's wave-2 reseed.
	qaTombPutProgress(t, j, j.admin, ep1Old.ID, qaTombPosACarry)
	stampACarry := qaTombPutWatched(t, j, j.admin, ep1Old.ID, qaTombPosACarry)
	qaTombPutProgress(t, j, j.user, ep2Old.ID, qaTombPosBStranded)
	stampBStranded := qaTombPutWatched(t, j, j.user, ep2Old.ID, qaTombPosBStranded)

	db := qaTombOpenLedger(t, j)
	if got := qaTombProgressSlots(t, db, ep1Old.ID); len(got) != 1 || got[0] != qaTombPosACarry {
		t.Fatalf("seed: E01-old progress slots = %v, want exactly slot 0 at %d", got, qaTombPosACarry)
	}
	if got := qaTombWatchedRows(t, db, ep1Old.ID); len(got) != 1 || got[0].CompletedAt != stampACarry {
		t.Fatalf("seed: E01-old watched rows = %v, want slot 0 stamped %s", got, stampACarry)
	}
	if got := qaTombProgressSlots(t, db, ep2Old.ID); len(got) != 1 || got[j.userID] != qaTombPosBStranded {
		t.Fatalf("seed: E02-old progress slots = %v, want exactly user %d at %d", got, j.userID, qaTombPosBStranded)
	}
	if got := qaTombWatchedRows(t, db, ep2Old.ID); len(got) != 1 || got[j.userID].CompletedAt != stampBStranded {
		t.Fatalf("seed: E02-old watched rows = %v, want user %d stamped %s", got, j.userID, stampBStranded)
	}

	// ---- THE RENAME + the rescan to a clean drain ----------------------------
	//
	// The directory gains a bracketed release year — the releasename grammar
	// strips it, the parsed title (and therefore the search title and the
	// stub's candidate) is byte-stable across the rename; the FILE paths
	// change, so every episode's stamped absolute_path goes dead and the item
	// sweep tombstones the rows (disk truth via stat), while the rescan
	// creates the successor rows.
	if err := os.Rename(filepath.Join(root, qaTombDirOld), filepath.Join(root, qaTombDirNew)); err != nil {
		t.Fatalf("rename serial directory: %v", err)
	}
	res2 := scanLibrary(t, j.client, j.srv.baseURL, j.admin, j.lib)
	if res2.Discovered != 4 || res2.Persisted != 4 {
		t.Fatalf("rename rescan: discovered=%d persisted=%d, want 4/4 (the renamed serial + its 3 episodes); warnings=%v",
			res2.Discovered, res2.Persisted, res2.Warnings)
	}
	if len(res2.Warnings) != 0 {
		t.Fatalf("rename rescan: warnings = %v, want none (a clean drain — the stat-miss tombstones are silent)", res2.Warnings)
	}
	qaTombWaitSettled(t, j)

	ep1New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp1New)
	ep2New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp2New)
	ep3New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombEp3New)
	if ep1New.ID == ep1Old.ID || ep2New.ID == ep2Old.ID || ep3New.ID == ep3Old.ID {
		t.Fatalf("rename rescan reused a dead id: old [%s %s %s] new [%s %s %s]",
			ep1Old.ID, ep2Old.ID, ep3Old.ID, ep1New.ID, ep2New.ID, ep3New.ID)
	}

	// The tombstones: the dead rows read deleted RAW (the serve side may or
	// may not list them — task 3.2's default exclusion is out of this task's
	// scope; the raw store read is the stable oracle). The old series row
	// tombstoned with them; the successor series row is live.
	for _, it := range []struct{ label, id string }{
		{"E01-old", ep1Old.ID}, {"E02-old", ep2Old.ID}, {"E03-old", ep3Old.ID},
	} {
		if got := qaTombRowStatus(t, db, "items", it.id); got != "deleted" {
			t.Errorf("rename rescan: %s raw status = %q, want deleted (the item sweep's stat miss)", it.label, got)
		}
	}
	if got := qaTombRowStatus(t, db, "series", oldSeriesID); got != "deleted" {
		t.Errorf("rename rescan: old series raw status = %q, want deleted (the series sweep)", got)
	}
	var newSeriesID string
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.lib) {
		if sr.RelativePath == qaTombDirNew {
			newSeriesID = sr.ID
		}
	}
	if newSeriesID == "" || newSeriesID == oldSeriesID {
		t.Errorf("rename rescan: successor series row = %q, want a NEW identity for %q", newSeriesID, qaTombDirNew)
	}

	// The successor episodes settled into the SAME empty-floor identity (the
	// legs decide the match — the rename must not disturb them).
	for rel, dto := range map[string]itemDTO{
		qaTombEp1New: ep1New, qaTombEp2New: ep2New, qaTombEp3New: ep3New,
	} {
		qaTombAssertEpisodeIdentity(t, "rename rescan", rel, qaTombDoc(t, dto.Document), int64(rel[len(rel)-len("E01.mkv")+2]-'0'))
	}

	// THE CONVERGENCE PASS (task 2.7): the amended identity (contracts/2.5)
	// floors every episode match on the SERIES rows' parser-composed titles —
	// facts that land on the new series row's own settle, which the rename
	// pass's drain order puts AFTER the item settles (derive walks items
	// before series). The rename pass's adoption fire therefore floors "" and
	// refuses; adoption re-fires at every settle (the bridge's documented
	// convergence law — a mixed-enrichment pair mismatches that wave and
	// converges on the next), so one operator refresh on the live successors —
	// 2.4's own wave-2 idiom — re-settles them under the now-present series
	// title and the carry lands deterministically before the acceptance reads
	// below. 2.4's assert bytes are untouched by this insertion.
	qaTombRefresh(t, j, ep1New.ID, ep2New.ID, ep3New.ID)
	qaTombWaitSettled(t, j)

	// ---- WAVE-1 ACCEPTANCE: the carry (the JoJo acceptance at code level) ----
	//
	// The settle hook fired adoption for each successor row as it settled:
	// the stranded position and watched-ledger row land on the
	// identity-matched live item ids ("" floors equal, legs equal), the moved
	// watched row carries completed_at verbatim and re-points
	// series_relative_path, the dead rows hold NOTHING (the moves' DELETE
	// half), and E03-new — identity (1,3), never seeded — carries nothing.
	//
	// CONTRACT MISMATCH: this is where the flagged defect bites. The dead
	// rows' perpetually-pending (item, shikimori) pairs re-dispatch on THIS
	// derive pass alongside the successors' parser pairs; a dead row's
	// skip-settle fires the unguarded adoption hook (queue.go:750) and its
	// self-move destroys the stranded stock (store/adopt.go: the NOT EXISTS
	// sees the source row itself, the DELETE is unconditional). Derivation
	// walks ORDER BY id over random hex ids (items.go:125), so whether the
	// destroyer or the carrier wins is random per run — a red below with the
	// stock already gone from the dead id is the defect's receipt, not a
	// fixture failure.
	if got := qaTombProgressSlots(t, db, ep1New.ID); len(got) != 1 || got[0] != qaTombPosACarry {
		t.Errorf("wave-1 acceptance: E01-new progress slots = %v, want exactly slot 0 at %d (the stranded position carried)", got, qaTombPosACarry)
	}
	if recs := qaTombWatchedRows(t, db, ep1New.ID); len(recs) != 1 {
		t.Errorf("wave-1 acceptance: E01-new watched rows = %v, want exactly slot 0 (the stranded ledger row carried)", recs)
	} else if rec := recs[0]; rec.CompletedAt != stampACarry {
		t.Errorf("wave-1 acceptance: E01-new watched completed_at = %q, want the stranded stamp %q verbatim", rec.CompletedAt, stampACarry)
	} else if rec.SeriesPath != qaTombDirNew {
		t.Errorf("wave-1 acceptance: E01-new watched series_relative_path = %q, want the successor path %q (the move re-points it)", rec.SeriesPath, qaTombDirNew)
	}
	if got := qaTombProgressSlots(t, db, ep2New.ID); len(got) != 1 || got[j.userID] != qaTombPosBStranded {
		t.Errorf("wave-1 acceptance: E02-new progress slots = %v, want exactly user %d at %d (the stranded position carried)", got, j.userID, qaTombPosBStranded)
	}
	if recs := qaTombWatchedRows(t, db, ep2New.ID); len(recs) != 1 {
		t.Errorf("wave-1 acceptance: E02-new watched rows = %v, want exactly user %d (the stranded ledger row carried)", recs, j.userID)
	} else if rec := recs[j.userID]; rec.CompletedAt != stampBStranded {
		t.Errorf("wave-1 acceptance: E02-new watched completed_at = %q, want the stranded stamp %q verbatim", rec.CompletedAt, stampBStranded)
	} else if rec.SeriesPath != qaTombDirNew {
		t.Errorf("wave-1 acceptance: E02-new watched series_relative_path = %q, want the successor path %q", rec.SeriesPath, qaTombDirNew)
	}
	if got := qaTombRowCount(t, db, "playback_progress", ep3New.ID); got != 0 {
		t.Errorf("wave-1 acceptance: E03-new progress rows = %d, want 0 (identity (1,3) was never seeded — the legs must not cross-carry)", got)
	}
	if got := qaTombRowCount(t, db, "watched_items", ep3New.ID); got != 0 {
		t.Errorf("wave-1 acceptance: E03-new watched rows = %d, want 0 (identity (1,3) was never seeded)", got)
	}
	for _, it := range []struct{ label, itemID string }{
		{"E01-old", ep1Old.ID}, {"E02-old", ep2Old.ID}, {"E03-old", ep3Old.ID},
	} {
		if got := qaTombRowCount(t, db, "playback_progress", it.itemID); got != 0 {
			t.Errorf("wave-1 acceptance: %s playback_progress rows = %d, want 0 (the dead rows hold nothing)", it.label, got)
		}
		if got := qaTombRowCount(t, db, "watched_items", it.itemID); got != 0 {
			t.Errorf("wave-1 acceptance: %s watched_items rows = %d, want 0 (the dead rows hold nothing)", it.label, got)
		}
	}

	// The wire agrees with the ledger on the live ids (viewer-scoped slots).
	if pos, ok := qaTombGetProgressPos(t, j, j.admin, ep1New.ID); !ok || pos != qaTombPosACarry {
		t.Errorf("wave-1 acceptance: admin GET progress E01-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosACarry)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, ep2New.ID); !ok || pos != qaTombPosBStranded {
		t.Errorf("wave-1 acceptance: user GET progress E02-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosBStranded)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, ep3New.ID); ok {
		t.Errorf("wave-1 acceptance: user GET progress E03-new = (%d,true), want 404 (nothing carried to it)", pos)
	}

	// ---- Series B joins the fixture (task 2.7's no-cross-carry wave) --------
	//
	// B enters AFTER 2.4's waves so every byte-frozen assert above keeps its
	// authored truth (wave 0 and the rename rescan counted Series A alone).
	// B brings its own directory, its own bracketed-tag rename, its own dead
	// row set and stranded viewer stock — and one structural probe: E04
	// exists only BEFORE the rename, so B's dead row for it has NO successor.
	// Its stranded stock has no same-series match and must survive EVERY
	// queue pass retained (2.6's laws through the real chain — the destroyer
	// the 2.4 receipt flagged destroyed exactly this class of stock); before
	// the bridge (2.5) the whole library shared one legs-only identity, so
	// B's stock was everyone's carry target. From here on, "viewer B" (2.4's
	// j.user slot) and "Series B" (this wave) are distinct things.
	qaTombWriteSeriesB(t, root)
	resB := scanLibrary(t, j.client, j.srv.baseURL, j.admin, j.lib)
	if resB.Discovered != 9 || resB.Persisted != 9 {
		t.Fatalf("B intro scan: discovered=%d persisted=%d, want 9/9 (Series A's 4 re-observed rows + B's serial record + 4 episodes); warnings=%v",
			resB.Discovered, resB.Persisted, resB.Warnings)
	}
	if len(resB.Warnings) != 0 {
		t.Fatalf("B intro scan: warnings = %v, want none (a clean fixture library)", resB.Warnings)
	}
	qaTombWaitSettled(t, j)

	bEp1Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp1Old)
	bEp2Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp2Old)
	bEp3Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp3Old)
	bEp4Old := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp4Old)

	// B's identity precondition, pinned as actual behavior: the same
	// empty-floor legs-only episode shape as Series A's ((1, N) parse legs,
	// no title floor, no shikimori namespace), and B's series row carrying
	// its parser-composed title through the REAL scan chain — the bridge
	// floor both sides of every B carry resolve.
	for rel, dto := range map[string]itemDTO{
		qaTombBEp1Old: bEp1Old, qaTombBEp2Old: bEp2Old,
		qaTombBEp3Old: bEp3Old, qaTombBEp4Old: bEp4Old,
	} {
		qaTombAssertEpisodeIdentity(t, "B intro", rel, qaTombDoc(t, dto.Document), int64(rel[len(rel)-len("E01.mkv")+2]-'0'))
	}
	var bOldSeriesID string
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.lib) {
		if sr.RelativePath == qaTombDirBOld {
			bOldSeriesID = sr.ID
			qaTombNamespace(t, qaTombDoc(t, sr.Document), "shikimori") // B's own upstream candidate — landed
			if got := qaTombSeriesParserTitle(t, sr.Document); got != qaTombSearchTitleB {
				t.Fatalf("B intro: series parser title = %q, want %q (the real serial-parser Merge composes it from dir_name_raw)", got, qaTombSearchTitleB)
			}
		}
	}
	if bOldSeriesID == "" {
		t.Fatalf("B intro scan: no series row at %q", qaTombDirBOld)
	}

	// B's rename: the SAME bracketed-tag shape as A's — the releasename
	// grammar strips the year tag and the season marker, so the parsed title
	// (and with it the stub's candidate) is byte-stable while every episode
	// file path dies. E04's file is REMOVED, not renamed: its row tombstones
	// with no successor.
	if err := os.Remove(filepath.Join(root, qaTombDirBOld, "Beacon Line S01E04.mkv")); err != nil {
		t.Fatalf("remove B E04: %v", err)
	}
	if err := os.Rename(filepath.Join(root, qaTombDirBOld), filepath.Join(root, qaTombDirBNew)); err != nil {
		t.Fatalf("rename B directory: %v", err)
	}
	resB2 := scanLibrary(t, j.client, j.srv.baseURL, j.admin, j.lib)
	if resB2.Discovered != 8 || resB2.Persisted != 8 {
		t.Fatalf("B rename rescan: discovered=%d persisted=%d, want 8/8 (Series A's 4 unchanged rows + B's renamed serial record + 3 episodes); warnings=%v",
			resB2.Discovered, resB2.Persisted, resB2.Warnings)
	}
	if len(resB2.Warnings) != 0 {
		t.Fatalf("B rename rescan: warnings = %v, want none (the E04 stat-miss tombstone is silent)", resB2.Warnings)
	}
	qaTombWaitSettled(t, j)

	bEp1New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp1New)
	bEp2New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp2New)
	bEp3New := qaSerialItemByRel(t, j.client, j.srv.baseURL, j.admin, j.lib, qaTombBEp3New)
	if bEp1New.ID == bEp1Old.ID || bEp2New.ID == bEp2Old.ID || bEp3New.ID == bEp3Old.ID {
		t.Fatalf("B rename rescan reused a dead id: old [%s %s %s] new [%s %s %s]",
			bEp1Old.ID, bEp2Old.ID, bEp3Old.ID, bEp1New.ID, bEp2New.ID, bEp3New.ID)
	}

	// B's tombstones, raw (the stable oracle): all four dead B rows plus B's
	// dead series row. B's successor episodes settled into the same
	// empty-floor identity, and B's successor series row is live with the
	// SAME parser title — the rename-stability the bridge carries on. A's
	// successor series is re-pinned beside it: the two titles are the
	// bridge's whole discrimination — equal per series, never equal across
	// series.
	for _, it := range []struct{ label, id string }{
		{"B-E01-old", bEp1Old.ID}, {"B-E02-old", bEp2Old.ID},
		{"B-E03-old", bEp3Old.ID}, {"B-E04-old", bEp4Old.ID},
	} {
		if got := qaTombRowStatus(t, db, "items", it.id); got != "deleted" {
			t.Errorf("B rename rescan: %s raw status = %q, want deleted (the item sweep's stat miss)", it.label, got)
		}
	}
	if got := qaTombRowStatus(t, db, "series", bOldSeriesID); got != "deleted" {
		t.Errorf("B rename rescan: B-old series raw status = %q, want deleted (the series sweep)", got)
	}
	for rel, dto := range map[string]itemDTO{
		qaTombBEp1New: bEp1New, qaTombBEp2New: bEp2New, qaTombBEp3New: bEp3New,
	} {
		qaTombAssertEpisodeIdentity(t, "B rename rescan", rel, qaTombDoc(t, dto.Document), int64(rel[len(rel)-len("E01.mkv")+2]-'0'))
	}
	var bNewSeriesID string
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.lib) {
		switch sr.RelativePath {
		case qaTombDirBNew:
			bNewSeriesID = sr.ID
			if got := qaTombSeriesParserTitle(t, sr.Document); got != qaTombSearchTitleB {
				t.Errorf("B rename rescan: successor series parser title = %q, want the rename-stable %q", got, qaTombSearchTitleB)
			}
		case qaTombDirNew:
			if got := qaTombSeriesParserTitle(t, sr.Document); got != qaTombSearchTitle {
				t.Errorf("B rename rescan: A successor series parser title = %q, want %q (the two series' titles must stay distinct)", got, qaTombSearchTitle)
			}
		}
	}
	if bNewSeriesID == "" || bNewSeriesID == bOldSeriesID {
		t.Errorf("B rename rescan: successor series row = %q, want a NEW identity for %q", bNewSeriesID, qaTombDirBNew)
	}

	// ---- B's stranded stock, seeded ON THE DEAD rows -------------------------
	//
	// Dead-id writes are legal (the store reads behind PUT progress/state are
	// status-unfiltered — 2.4's wave-2 precedent). Seeding AFTER B's rename
	// settle is what makes 2.4's wave-2 refresh the cross-carry detector: B's
	// dead rows hold REAL stock while A's live successors re-settle and walk
	// them as candidates, and the bridge must refuse every pair (equal legs,
	// "" floors, differing series titles). B's own carry has not fired yet —
	// B's live successors hold nothing.
	qaTombPutProgress(t, j, j.admin, bEp1Old.ID, qaTombPosBEp1)
	stampBEp1 := qaTombPutWatched(t, j, j.admin, bEp1Old.ID, qaTombPosEchoUnknown)
	qaTombPutProgress(t, j, j.user, bEp2Old.ID, qaTombPosBEp2)
	stampBEp2 := qaTombPutWatched(t, j, j.user, bEp2Old.ID, qaTombPosEchoUnknown)
	qaTombPutProgress(t, j, j.user, bEp3Old.ID, qaTombPosBEp3)
	stampBEp3 := qaTombPutWatched(t, j, j.user, bEp3Old.ID, qaTombPosEchoUnknown)
	qaTombPutProgress(t, j, j.admin, bEp4Old.ID, qaTombPosBEp4)
	stampBEp4 := qaTombPutWatched(t, j, j.admin, bEp4Old.ID, qaTombPosEchoUnknown)
	// The seed preconditions, pinned raw: the dead B stock is REAL before any
	// pass sees it — the retention and refusal asserts below mean something
	// only against actual rows.
	for _, it := range []struct {
		label     string
		itemID    string
		wantUser  int64
		wantPos   int64
		wantStamp string
	}{
		{"B-E01-old", bEp1Old.ID, 0, qaTombPosBEp1, stampBEp1},
		{"B-E02-old", bEp2Old.ID, j.userID, qaTombPosBEp2, stampBEp2},
		{"B-E03-old", bEp3Old.ID, j.userID, qaTombPosBEp3, stampBEp3},
		{"B-E04-old", bEp4Old.ID, 0, qaTombPosBEp4, stampBEp4},
	} {
		if got := qaTombProgressSlots(t, db, it.itemID); len(got) != 1 || got[it.wantUser] != it.wantPos {
			t.Fatalf("B seed: %s progress slots = %v, want exactly slot %d at %d", it.label, got, it.wantUser, it.wantPos)
		}
		if recs := qaTombWatchedRows(t, db, it.itemID); len(recs) != 1 || recs[it.wantUser].CompletedAt != it.wantStamp {
			t.Fatalf("B seed: %s watched rows = %v, want slot %d stamped %s", it.label, recs, it.wantUser, it.wantStamp)
		}
	}

	// THE LIVE-WRITE SLOT (task 2.7): the viewer clears their wave-1 carried
	// watched row on E02-new before 2.4's live write — the watched ledger is
	// INSERT-only (`ON CONFLICT(user_id, item_id) DO NOTHING`,
	// internal/store/recs.go InsertWatched), so a fresh live stamp can only
	// land in an EMPTY slot; carried verbatim, the wave-1 stamp would otherwise
	// outlive the write and 2.4's wave-2 assert (which wants the live write's
	// stamp on the row) could never hold. The unwatch is the real viewer flow
	// (DeleteWatched: the ledger row removed, the resume point reset to the
	// explicit 0), and 2.4's live write below re-inserts against the freed
	// slot — proving the fresh write wins against the re-seeded stranded stock.
	{
		var echo struct {
			ItemID string `json:"item_id"`
			State  string `json:"state"`
		}
		status := doRequest(t, j.client, http.MethodPut, j.srv.baseURL+"/api/v1/items/"+ep2New.ID+"/state", j.user,
			map[string]string{"state": "unwatched"}, &echo)
		if status != http.StatusOK {
			t.Fatalf("PUT state unwatched %s: HTTP %d, want 200 (the viewer clears their carried state before the live re-watch)", ep2New.ID, status)
		}
	}

	// ---- wave 2 seeds: the conflicting live row + the carry leg's stock ------
	//
	// B writes BOTH rows on the live successor (position + watched state) —
	// the rows that must win their slots in the wave-2 adoption. B re-seeds
	// stranded stock on E02-old (dead-id writes stay legal: the store reads
	// behind PUT progress/state are status-unfiltered), and A seeds the
	// E03-old stock for the wave-2 carry. Wave 2 re-fires adoption
	// deterministically through the REAL operator surface: the refresh strips
	// + re-runs the parser namespace on exactly the three successor rows
	// (dead rows untouched), their re-settle re-fires the settle hook.
	qaTombPutProgress(t, j, j.user, ep2New.ID, qaTombPosBLive)
	stampBLive := qaTombPutWatched(t, j, j.user, ep2New.ID, qaTombPosBLive)
	qaTombPutProgress(t, j, j.user, ep2Old.ID, qaTombPosBReseed)
	stampBReseed := qaTombPutWatched(t, j, j.user, ep2Old.ID, qaTombPosEchoUnknown)
	qaTombPutProgress(t, j, j.admin, ep3Old.ID, qaTombPosACarry3)
	stampACarry3 := qaTombPutWatched(t, j, j.admin, ep3Old.ID, qaTombPosEchoUnknown)
	// The reseed precondition, pinned: the dead-id stock is REAL before the
	// refresh — the conflict leg refuses actual rows, never a vacuum.
	if got := qaTombProgressSlots(t, db, ep2Old.ID); len(got) != 1 || got[j.userID] != qaTombPosBReseed {
		t.Fatalf("wave-2 seed: E02-old progress slots = %v, want exactly user %d at %d", got, j.userID, qaTombPosBReseed)
	}
	if got := qaTombWatchedRows(t, db, ep2Old.ID); len(got) != 1 || got[j.userID].CompletedAt != stampBReseed {
		t.Fatalf("wave-2 seed: E02-old watched rows = %v, want user %d stamped %s", got, j.userID, stampBReseed)
	}
	if got := qaTombProgressSlots(t, db, ep3Old.ID); len(got) != 1 || got[0] != qaTombPosACarry3 {
		t.Fatalf("wave-2 seed: E03-old progress slots = %v, want exactly slot 0 at %d", got, qaTombPosACarry3)
	}

	qaTombRefresh(t, j, ep1New.ID, ep2New.ID, ep3New.ID)
	qaTombWaitSettled(t, j)

	// ---- WAVE-2 ACCEPTANCE: the live row wins, the other viewer still carries
	//
	// 1. E01-new is UNCHANGED from wave 1 — its rows are byte-stable across
	//    the re-fire (the dead ids it could adopt from hold nothing: the
	//    moves are idempotent no-ops).
	if got := qaTombProgressSlots(t, db, ep1New.ID); len(got) != 1 || got[0] != qaTombPosACarry {
		t.Errorf("wave-2 acceptance: E01-new progress slots = %v, want unchanged slot 0 at %d (the carry is stable across re-adoption)", got, qaTombPosACarry)
	}
	if recs := qaTombWatchedRows(t, db, ep1New.ID); len(recs) != 1 || recs[0].CompletedAt != stampACarry {
		t.Errorf("wave-2 acceptance: E01-new watched rows = %v, want the unchanged wave-1 stamp %q", recs, stampACarry)
	}
	// 2. The conflicting live row wins its slot: B's rows on E02-new are the
	//    LIVE writes byte-identical — the re-seeded dead-id stock (position
	//    22, its own stamp) was deleted, never moved.
	if got := qaTombProgressSlots(t, db, ep2New.ID); len(got) != 1 || got[j.userID] != qaTombPosBLive {
		t.Errorf("wave-2 acceptance: E02-new progress slots = %v, want exactly user %d at %d (the live row wins its slot)", got, j.userID, qaTombPosBLive)
	}
	if recs := qaTombWatchedRows(t, db, ep2New.ID); len(recs) != 1 {
		t.Errorf("wave-2 acceptance: E02-new watched rows = %v, want exactly user %d (the live row wins its slot)", recs, j.userID)
	} else if rec := recs[j.userID]; rec.CompletedAt != stampBLive {
		t.Errorf("wave-2 acceptance: E02-new watched completed_at = %q, want the live write %q (the re-seeded stranded row must not land)", rec.CompletedAt, stampBLive)
	} else if rec.SeriesPath != qaTombDirNew {
		t.Errorf("wave-2 acceptance: E02-new watched series_relative_path = %q, want the successor path %q", rec.SeriesPath, qaTombDirNew)
	}
	// 3. The other viewer's stranded row still carries: A's fresh E03-old
	//    stock lands on E03-new in wave 2.
	if got := qaTombProgressSlots(t, db, ep3New.ID); len(got) != 1 || got[0] != qaTombPosACarry3 {
		t.Errorf("wave-2 acceptance: E03-new progress slots = %v, want exactly slot 0 at %d (the other viewer's stranded row still carries)", got, qaTombPosACarry3)
	}
	if recs := qaTombWatchedRows(t, db, ep3New.ID); len(recs) != 1 {
		t.Errorf("wave-2 acceptance: E03-new watched rows = %v, want exactly slot 0", recs)
	} else if rec := recs[0]; rec.CompletedAt != stampACarry3 || rec.SeriesPath != qaTombDirNew {
		t.Errorf("wave-2 acceptance: E03-new watched row = %+v, want the stranded stamp %q verbatim re-pointed to %q", rec, stampACarry3, qaTombDirNew)
	}
	// 4. The dead rows hold NOTHING — every tombstoned id's slot stock is
	//    gone (wave 1's moves and wave 2's refused-stock deletes), on BOTH
	//    ledgers. Raw reads only: the joined wire reads hide deleted rows and
	//    could never prove this.
	for _, it := range []struct{ label, itemID string }{
		{"E01-old", ep1Old.ID}, {"E02-old", ep2Old.ID}, {"E03-old", ep3Old.ID},
	} {
		if got := qaTombRowCount(t, db, "playback_progress", it.itemID); got != 0 {
			t.Errorf("wave-2 acceptance: %s playback_progress rows = %d, want 0 (the dead rows hold nothing)", it.label, got)
		}
		if got := qaTombRowCount(t, db, "watched_items", it.itemID); got != 0 {
			t.Errorf("wave-2 acceptance: %s watched_items rows = %d, want 0 (the dead rows hold nothing)", it.label, got)
		}
	}
	// 5. No cross-identity leak: every carried row sits ONLY on its
	//    identity-matched successor and its own viewer's slot.
	if recs := qaTombWatchedRows(t, db, ep1New.ID); len(recs) != 0 && recs[j.userID].CompletedAt != "" {
		t.Errorf("wave-2 acceptance: E01-new holds user watched rows %v, want none (identity (1,1) never matches (1,2))", recs)
	}
	if got := qaTombProgressSlots(t, db, ep2New.ID); len(got) != 0 && got[0] != 0 {
		t.Errorf("wave-2 acceptance: E02-new holds slot-0 progress rows %v, want none (identity (1,2) never matches (1,1)/(1,3))", got)
	}
	if got := qaTombProgressSlots(t, db, ep3New.ID); len(got) != 0 && got[j.userID] != 0 {
		t.Errorf("wave-2 acceptance: E03-new holds user progress rows %v, want none (identity (1,3) never matches (1,2))", got)
	}
	// 6. The wire serves the final state on the live ids.
	if pos, ok := qaTombGetProgressPos(t, j, j.admin, ep1New.ID); !ok || pos != qaTombPosACarry {
		t.Errorf("wave-2 acceptance: admin GET progress E01-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosACarry)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, ep2New.ID); !ok || pos != qaTombPosBLive {
		t.Errorf("wave-2 acceptance: user GET progress E02-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosBLive)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, ep3New.ID); ok {
		t.Errorf("wave-2 acceptance: user GET progress E03-new = (%d,true), want 404 (another viewer's slot)", pos)
	}

	// ---- WAVE-2 CARRY: B's stock rode 2.4's own pass -------------------------
	//
	// B's stock was seeded into a SETTLED library, so the first queue pass that
	// sees it is 2.4's wave-2 refresh settle above: every live row with an
	// absent namespace re-dispatches on every derive pass (the documented
	// terminal-stamp gap — 2.6 rules the stamp check out of scope), and every
	// live settle re-fires adoption over EVERY dead candidate of the library.
	// That motion is the amended chain's honest end state, not a leak: the
	// bridge routes each B row's stock onto B's OWN successor (same
	// parser-composed series title, equal legs) and refuses every A-side pair —
	// 2.4's wave-2 asserts just pinned A's successors' exact slots with B's
	// stock in play. assertBEndState pins the whole B end state of that pass,
	// raw; the wave-B pass below re-pins it byte-identical (the moves are
	// idempotent — emptied sources carry nothing twice) while the probe moves.
	assertBEndState := func(phase string) {
		// B's live successors hold exactly B's own stranded stock: stamps
		// verbatim, series_relative_path re-pointed to B's live series path.
		// The exact slot maps are simultaneously the cross-negative (a): any
		// wrong-series carry corrupts a value, a stamp, or a path here.
		if got := qaTombProgressSlots(t, db, bEp1New.ID); len(got) != 1 || got[0] != qaTombPosBEp1 {
			t.Errorf("%s: B-E01-new progress slots = %v, want exactly slot 0 at %d (B's own stock carried; nothing foreign may land here)", phase, got, qaTombPosBEp1)
		}
		if recs := qaTombWatchedRows(t, db, bEp1New.ID); len(recs) != 1 {
			t.Errorf("%s: B-E01-new watched rows = %v, want exactly slot 0", phase, recs)
		} else if rec := recs[0]; rec.CompletedAt != stampBEp1 {
			t.Errorf("%s: B-E01-new watched completed_at = %q, want B's stranded stamp %q verbatim", phase, rec.CompletedAt, stampBEp1)
		} else if rec.SeriesPath != qaTombDirBNew {
			t.Errorf("%s: B-E01-new watched series_relative_path = %q, want B's live series path %q (the move re-points it)", phase, rec.SeriesPath, qaTombDirBNew)
		}
		if got := qaTombProgressSlots(t, db, bEp2New.ID); len(got) != 1 || got[j.userID] != qaTombPosBEp2 {
			t.Errorf("%s: B-E02-new progress slots = %v, want exactly viewer slot %d at %d (B's own stock carried)", phase, got, j.userID, qaTombPosBEp2)
		}
		if recs := qaTombWatchedRows(t, db, bEp2New.ID); len(recs) != 1 {
			t.Errorf("%s: B-E02-new watched rows = %v, want exactly viewer slot %d", phase, recs, j.userID)
		} else if rec := recs[j.userID]; rec.CompletedAt != stampBEp2 {
			t.Errorf("%s: B-E02-new watched completed_at = %q, want B's stranded stamp %q verbatim", phase, rec.CompletedAt, stampBEp2)
		} else if rec.SeriesPath != qaTombDirBNew {
			t.Errorf("%s: B-E02-new watched series_relative_path = %q, want B's live series path %q", phase, rec.SeriesPath, qaTombDirBNew)
		}
		if got := qaTombProgressSlots(t, db, bEp3New.ID); len(got) != 1 || got[j.userID] != qaTombPosBEp3 {
			t.Errorf("%s: B-E03-new progress slots = %v, want exactly viewer slot %d at %d (B's own stock carried)", phase, got, j.userID, qaTombPosBEp3)
		}
		if recs := qaTombWatchedRows(t, db, bEp3New.ID); len(recs) != 1 {
			t.Errorf("%s: B-E03-new watched rows = %v, want exactly viewer slot %d", phase, recs, j.userID)
		} else if rec := recs[j.userID]; rec.CompletedAt != stampBEp3 {
			t.Errorf("%s: B-E03-new watched completed_at = %q, want B's stranded stamp %q verbatim", phase, rec.CompletedAt, stampBEp3)
		} else if rec.SeriesPath != qaTombDirBNew {
			t.Errorf("%s: B-E03-new watched series_relative_path = %q, want B's live series path %q", phase, rec.SeriesPath, qaTombDirBNew)
		}
		// The carried-from rows hold NOTHING (the moves' DELETE half, raw).
		for _, it := range []struct{ label, itemID string }{
			{"B-E01-old", bEp1Old.ID}, {"B-E02-old", bEp2Old.ID}, {"B-E03-old", bEp3Old.ID},
		} {
			if got := qaTombRowCount(t, db, "playback_progress", it.itemID); got != 0 {
				t.Errorf("%s: %s playback_progress rows = %d, want 0 (the stock moved)", phase, it.label, got)
			}
			if got := qaTombRowCount(t, db, "watched_items", it.itemID); got != 0 {
				t.Errorf("%s: %s watched_items rows = %d, want 0 (the stock moved)", phase, it.label, got)
			}
		}
		// The no-successor dead row's stock is RETAINED through the pass: no
		// (1,4) legs match anywhere, so every adoption fire over it is a bridge
		// refusal — 2.6's survival law over a REAL row, walked by both passes.
		qaTombAssertRetainedStock(t, phase, "B-E04-old", db, bEp4Old.ID, 0, qaTombPosBEp4, stampBEp4, qaTombDirBOld)
	}
	assertBEndState("wave-2 carry")

	// ---- the vice-versa probe: A's dead E01-old re-arms ----------------------
	//
	// Seeded AFTER the wave-2 asserts (which pin E01-old holding nothing), on
	// the USER slot — the slot A-E01-new does NOT hold (its carried stock is
	// admin's). On the next pass A-E01-new settles (it re-dispatches every
	// derive pass — the terminal-stamp gap), the bridge matches its own dead
	// sibling (same "Anchor Point" title, equal (1,1) legs), and the probe
	// CARRIES WITHIN A, landing in ep1-new's empty user slot. That motion is
	// the vice-versa detector: B's successors settle in the same pass, and if
	// the bridge leaked across series the probe would land on (or be
	// refuse-deleted against) a B row instead — corrupting the exact B end
	// state re-pinned below. An admin-slot probe could not prove a destination
	// here: ep1-new's admin slot is occupied (the wave-1 carry), so the
	// live-row-wins law would refuse-delete the probe silently — the user slot
	// is what makes the probe's landing PROVABLE.
	qaTombPutProgress(t, j, j.user, ep1Old.ID, qaTombPosAXProbe)
	stampAXProbe := qaTombPutWatched(t, j, j.user, ep1Old.ID, qaTombPosEchoUnknown)
	if got := qaTombProgressSlots(t, db, ep1Old.ID); len(got) != 1 || got[j.userID] != qaTombPosAXProbe {
		t.Fatalf("probe seed: A-E01-old progress slots = %v, want exactly user %d at %d", got, j.userID, qaTombPosAXProbe)
	}
	if recs := qaTombWatchedRows(t, db, ep1Old.ID); len(recs) != 1 || recs[j.userID].CompletedAt != stampAXProbe {
		t.Fatalf("probe seed: A-E01-old watched rows = %v, want user %d stamped %s", recs, j.userID, stampAXProbe)
	}

	// ---- WAVE B: the probe's pass + the end state's stability -----------------
	//
	// The same deterministic re-fire surface as 2.4's wave 2: the refresh
	// strips + re-runs the parser namespace on exactly B's three successor
	// rows (dead rows untouched); their re-settles re-fire adoption, and every
	// other live row re-dispatches in the same pass — including A-E01-new,
	// whose settle sweeps the re-armed probe below. Nothing is left to carry:
	// the moves are idempotent, so B's end state must re-pin BYTE-IDENTICAL —
	// the second pass proves stability, not a second carry.
	qaTombRefresh(t, j, bEp1New.ID, bEp2New.ID, bEp3New.ID)
	qaTombWaitSettled(t, j)

	assertBEndState("wave-B stability")

	// The probe's END STATE (the vice-versa leg of (a), resolved): it carried
	// WITHIN A — A-E01-new's empty user slot holds exactly the probe (position
	// verbatim; the watched row's stamp verbatim, re-pointed to A's live
	// series path), the dead row holds nothing, and B's end state above is
	// unperturbed. Any cross-series leak would have put the probe on a B row
	// (or refuse-deleted it against one) instead of here.
	if got := qaTombProgressSlots(t, db, ep1New.ID); len(got) != 2 || got[0] != qaTombPosACarry || got[j.userID] != qaTombPosAXProbe {
		t.Errorf("wave-B retention: A-E01-new probe progress slots = %v, want exactly slot 0 at %d (the wave-1 carry) + user %d at %d (the probe carried within A — its own series, its own legs)", got, qaTombPosACarry, j.userID, qaTombPosAXProbe)
	}
	if recs := qaTombWatchedRows(t, db, ep1New.ID); len(recs) != 2 || recs[0].CompletedAt != stampACarry || recs[j.userID].CompletedAt != stampAXProbe || recs[j.userID].SeriesPath != qaTombDirNew {
		t.Errorf("wave-B retention: A-E01-new watched rows = %v, want admin (the wave-1 carry, stamp %q) + user (the probe, stamp %q verbatim re-pointed to %q)", recs, stampACarry, stampAXProbe, qaTombDirNew)
	}
	if got := qaTombRowCount(t, db, "playback_progress", ep1Old.ID); got != 0 {
		t.Errorf("wave-B retention: A-E01-old playback_progress rows = %d, want 0 (the probe moved off)", got)
	}
	if got := qaTombRowCount(t, db, "watched_items", ep1Old.ID); got != 0 {
		t.Errorf("wave-B retention: A-E01-old watched_items rows = %d, want 0 (the probe moved off)", got)
	}

	// The wire serves B's carried state on the live ids, and the retained
	// stock stays INERT: join-invisible on the wire (404), feeding no served
	// read while keyed to its dead id (adoption or self-heal re-keys it —
	// outside this joint's waves).
	if pos, ok := qaTombGetProgressPos(t, j, j.admin, bEp1New.ID); !ok || pos != qaTombPosBEp1 {
		t.Errorf("wave-B acceptance: admin GET progress B-E01-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosBEp1)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, bEp2New.ID); !ok || pos != qaTombPosBEp2 {
		t.Errorf("wave-B acceptance: user GET progress B-E02-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosBEp2)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, bEp3New.ID); !ok || pos != qaTombPosBEp3 {
		t.Errorf("wave-B acceptance: user GET progress B-E03-new = (%d,%v), want (%d,true)", pos, ok, qaTombPosBEp3)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.user, ep1New.ID); !ok || pos != qaTombPosAXProbe {
		t.Errorf("wave-B retention: user GET progress A-E01-new = (%d,%v), want (%d,true) (the probe is served on its live id)", pos, ok, qaTombPosAXProbe)
	}
	if pos, ok := qaTombGetProgressPos(t, j, j.admin, bEp4Old.ID); ok {
		t.Errorf("wave-B acceptance: admin GET progress B-E04-old = (%d,true), want 404 (retained stock is join-invisible — it feeds no served read)", pos)
	}
}
